mapper.select:
        select a.*
        from filing_materials a inner join proj_review_base_info b on a.object_id = b.id
        
            and a.approve_status != 'ABOLISH'
            
                and a.id IN
                
                    #{item}
                
            
            and a.filing_type=#{dto.filingType}
            and a.object_type=#{dto.objectType}
            and a.client_id=#{dto.clientId}
            and b.proj_name like CONCAT('%',#{dto.projName},'%')
            and b.proj_code like
                CONCAT('%',#{dto.projCode}, '%')
            
            and a.materials_desc like CONCAT('%',#{dto.materialsDesc}, '%')
            and a.dept_id=#{dto.bizDeptId}
            and a.user_id=#{dto.createById}
            and a.approve_status=#{dto.approveStatus}
            
                and a.approve_status IN
                
                    #{item}
                
            

            and a.first_commit_date >= #{dto.startDateFrom}
            and a.first_commit_date <= #{dto.startDateTo}
            and a.approve_date >= #{dto.endDateFrom}
            and a.approve_date <= #{dto.endDateTo}
            
                and
                (dept_id IN
                
                    #{item}
                
                or a.user_id = #{dto.currentUserId}
                )
            
        
        order by a.id desc

SELECT DISTINCT
fm.id as filingMaterialsId,
fm.filing_type as filingType,
fdf.financing_code as financingCode,
fdf.direct_financing_type as projClassify,
fdf.product_name as productName,
fdf.financing_status as financingStatus,
fdf.carry_interest_time as carryInterestTime,
fdf.duration_time as endDate,
fdf.fund_manager_id as fundManagerId,
fm.approve_status as approveStatus,
fm.approve_date as archiveDate
from filing_materials fm
inner join fund_direct_financing_base_info fdf on
fm.object_id = fdf.id
WHERE fm.object_type = 'FUND'

    and fdf.financing_code like CONCAT('%',#{req.financingCode}, '%')


    and fm.filing_type = #{req.filingType}


    and fdf.direct_financing_type = #{req.projClassify}


    and fdf.product_name like CONCAT('%',#{req.productName}, '%')


    and fdf.financing_status = #{req.financingStatus}


    and fdf.fund_manager_id = #{req.fundManagerId}


    
        
            and fm.approve_status = 'APPROVAL_PASS'
        
        
            and (fm.approve_status IS NULL OR fm.approve_status != 'APPROVAL_PASS')
        
    


    and fdf.carry_interest_time >= #{req.carryInterestTimeFrom}


    and fdf.carry_interest_time <= #{req.carryInterestTimeTo}


    and fdf.duration_time >= #{req.endDateFrom}


    and fdf.duration_time <= #{req.endDateTo}


    and fm.approve_date >= #{req.archiveDateFrom}


    and fm.approve_date <= #{req.archiveDateTo}

ORDER BY fdf.carry_interest_time DESC

    LIMIT 200

SELECT DISTINCT
fm.id as filingMaterialsId,
fm.filing_type as filingType,
ffb.financing_code as financingCode,
ffb.business_type as bizType,
ffc.organization_id as organizationId,
ffb.financing_status as financingStatus,
ffb.actual_loan_date as carryInterestTime,
ffb.actual_expire_date as endDate,
ffb.fund_manager_id as fundManagerId,
fm.approve_status as approveStatus,
fm.approve_date as archiveDate
from filing_materials fm
inner join fund_financing_base_info ffb on fm.object_id = ffb.id
inner join fund_financing_credit_ref ffc on ffc.financing_id = ffb.id
WHERE fm.object_type = 'FUND'

    and ffb.financing_code like CONCAT('%',#{req.financingCode}, '%')


    and fm.filing_type = #{req.filingType}


    and ffb.business_type = #{req.bizType}


    and ffc.organization_id = #{req.organizationId}


    and ffb.financing_status = #{req.financingStatus}


    and ffb.fund_manager_id = #{req.fundManagerId}


    
        
            and fm.approve_status = 'APPROVAL_PASS'
        
        
            and (fm.approve_status IS NULL OR fm.approve_status != 'APPROVAL_PASS')
        
    


    and ffb.actual_loan_date >= #{req.carryInterestTimeFrom}


    and ffb.actual_loan_date <= #{req.carryInterestTimeTo}


    and ffb.actual_expire_date >= #{req.endDateFrom}


    and ffb.actual_expire_date <= #{req.endDateTo}


    and fm.approve_date >= #{req.archiveDateFrom}


    and fm.approve_date <= #{req.archiveDateTo}

ORDER BY ffb.actual_loan_date DESC

    LIMIT 200

SELECT DISTINCT cbi.biz_dept_id AS bizDeptId, fm.client_id AS clientId, fm.proj_code AS projCode, cbi.proj_name AS projName, cbi.contract_code AS contractCode, cbi.risk_control_industry_classify AS riskControlIndustryClassify, cbi.proj_sponsor_user_id AS sponsorUserId, COALESCE( task.ASSIGNEE_, (SELECT GROUP_CONCAT(DISTINCT il.USER_ID_) FROM act_hi_identitylink il WHERE il.TASK_ID_ = act.TASK_ID_ AND il.TYPE_ IN ('participant', 'assignee')), '未知审批人' ) AS materialsReReviewUserId, -- 最后审批人 fm.flow_id AS processInstanceId, fm.start_date AS createTime, fm.approve_date AS endTime, fm.filing_overdue as archiveOverDueFlag, fm.supplement_filing_overdue as supplementDocOverdueFlag, fm.duration as duration, fm.materials_manager_review_duration as materialsManagerReviewDuration, fm.materials_manager_re_review_duration as materialsManagerReReviewDuration, fm.first_commit_date AS projectHostSubmitTime, fm.archive_pre_review_last_submit_time as archiveReviewSubmitTime, fm.archive_review_last_submit_time as archiveReReviewSubmitTime, fm.archive_pre_review_reject_count as archiveReviewRejectCount, fm.archive_review_reject_count as archiveReReviewRejectCount, fm.archive_pre_review_reject_reason_sum as archiveReviewRejectReason, fm.archive_review_reject_reason_sum as archiveReReviewRejectReason FROM filing_materials fm INNER JOIN contract_base_info cbi ON fm.contract_id = cbi.id INNER JOIN act_hi_actinst act ON fm.flow_id = act.PROC_INST_ID_ LEFT JOIN act_hi_taskinst task ON act.TASK_ID_ = task.ID_ INNER JOIN ( SELECT PROC_INST_ID_, MAX(END_TIME_) AS max_end_time FROM act_hi_actinst WHERE ACT_ID_ = 'userTask_review' AND DELETE_REASON_ is null GROUP BY PROC_INST_ID_ ) act_max ON act.PROC_INST_ID_ = act_max.PROC_INST_ID_ AND act.END_TIME_ = act_max.max_end_time WHERE fm.approve_status = 'APPROVAL_PASS' AND fm.object_type = 'PROJECT' AND fm.filing_type = 'BUSINESS_MATERIALS' AND act.ACT_ID_ = 'userTask_review'
AND fm.client_id = #{req.clientId}
AND fm.proj_code like CONCAT('%', #{req.projCode}, '%')
AND cbi.proj_name LIKE CONCAT('%', #{req.projName}, '%')
AND cbi.contract_code like CONCAT('%', #{req.contractCode}, '%')
AND cbi.biz_dept_id = #{req.bizDeptId}
AND cbi.risk_control_industry_classify = #{req.riskControlIndustryClassify}
AND cbi.proj_sponsor_user_id = #{req.sponsorUserId}
AND act.ASSIGNEE_ = #{req.materialsReReviewUserId}
AND fm.flow_id like CONCAT('%', #{req.processInstanceId}, '%')
AND fm.filing_overdue = #{req.archiveOverDueFlag}
AND fm.supplement_filing_overdue = #{req.supplementDocOverdueFlag}
AND fm.start_date >= #{req.createTimeFrom}
AND fm.start_date <= #{req.createTimeTo}
AND fm.approve_date >= #{req.endTimeFrom}
AND fm.approve_date <= #{req.endTimeTo}
ORDER BY fm.approve_date DESC
